-- 2026-08 quality repair: stage-specific camp messages are injected by events.
-- Keep the three seed rows as ordinary historical mail so row count is stable.
UPDATE messages
SET message_id = '<spring-pool-checklist-052@example.invalid>',
    subject = '春季泳池入场清单',
    from_addr = 'service@community-pool.example.invalid',
    date = '2026-05-18T09:30:00+08:00',
    body_text = '浅水区周末开放到 20:30；首次入场请带泳帽，并在前台核对储物柜规则。',
    is_read = 1,
    is_important = 0,
    size = 812,
    created_at = '2026-05-18T09:32:00+08:00'
WHERE message_id = 'msg_camp_brief_052';

UPDATE messages
SET message_id = '<bike-maintenance-receipt-052@example.invalid>',
    subject = '通勤车保养取车单',
    from_addr = 'desk@bike-repair.example.invalid',
    date = '2026-05-26T17:10:00+08:00',
    body_text = '刹车皮和胎压已复查，取车时请试握刹把；本单不含车辆租赁或课程服务。',
    is_read = 1,
    is_important = 0,
    size = 846,
    created_at = '2026-05-26T17:12:00+08:00'
WHERE message_id = 'msg_upgrade_1880_052';

UPDATE messages
SET message_id = '<family-august-note-052@example.invalid>',
    subject = '八月家庭聚餐预告',
    from_addr = 'family@updates.example.invalid',
    date = '2026-06-02T19:20:00+08:00',
    body_text = '家人暂定八月第二个周末聚餐，具体时间会在七月底另行确认。',
    is_read = 1,
    is_important = 0,
    size = 768,
    created_at = '2026-06-02T19:22:00+08:00'
WHERE message_id = 'msg_final_notice_052';

-- Remove generated “current status / next step / contact” boilerplate.  The
-- preceding sentence is the actual sender-authored business content.
UPDATE messages
SET body_text = trim(substr(body_text, 1, instr(body_text, '本次更新涉及') - 1))
WHERE instr(body_text, '本次更新涉及') > 0;

UPDATE messages
SET subject = replace(subject, '需要交叉核对', '信息待核实')
WHERE subject LIKE '%需要交叉核对%';

-- Long repeated notices are rewritten as concise mailbox messages rather than
-- slot-filled benchmark prose.
UPDATE messages SET body_text = '集合与泳道规则有变，头盔租赁待确认。'
WHERE body_text = '集合时间、泳池规则和退出机制已更新；头盔或租赁仍需自行确认。';
UPDATE messages SET body_text = '进阶课优惠仅供参考，报名付款未授权。'
WHERE body_text = '邮件介绍进阶课程和优惠，但报名与付款需要明确授权。';
UPDATE messages SET body_text = '新手泳道移至浅水区，入场前看公告。'
WHERE body_text = '周末新手泳道改到浅水区，入场前查看实时公告。';

UPDATE messages
SET subject = '远程值守排班确认',
    body_text = '周四晚远程值守由吴静接班，交接文档已放在原邮件线程；发布观察结束前请留在值守群。'
WHERE body_text LIKE '运营支持通知：远程值守排班%';
UPDATE messages
SET subject = '发布窗口调整记录',
    body_text = '客户把素材冻结时间提前到周三 16:00，版本负责人仍为李欣；附件中的回滚联系人没有变化。'
WHERE body_text LIKE '行政服务通知：发布窗口调整%';
UPDATE messages
SET subject = '新同事设备领取时间',
    body_text = '新同事周五 14:30 到前台领取电脑，账号开通由研发效能组另发确认。'
WHERE body_text LIKE '研发效能通知：新同事入职%';
UPDATE messages
SET subject = '测试环境发布时段',
    body_text = '测试环境计划周二 18:00 切换，若验收延期，原线程会给出新的观察结束时间。'
WHERE body_text LIKE '研发效能通知：发布窗口调整%';

-- 2026-08 second-pass manual-cat repair: recurring mailbox threads keep
-- their business topic but use varied recipient-facing facts instead of one
-- generated body frame and one generated subject suffix.
UPDATE messages
SET subject = trim(substr(subject, 1, instr(subject, '｜') - 1))
WHERE instr(subject, '｜') > 0;

UPDATE messages
SET body_text = CASE subject
  WHEN '家庭周末安排' THEN CASE ((rowid / 12) % 4)
    WHEN 0 THEN '周六午后家里安排清理储物间，预计 14:00 到 17:00 都有人进出。'
    WHEN 1 THEN '周日 11:30 家庭聚餐，长辈会提前半小时到，晚间时间暂时空着。'
    WHEN 2 THEN '本周末要陪家人去城西办事，返程时间取决于地铁换乘情况。'
    WHEN 3 THEN '家人把探访改到周六傍晚，具体结束时间会在当天上午确认。'
    ELSE '家人把探访改到周六傍晚，具体结束时间会在当天上午确认。' END
  WHEN '项目发布窗口' THEN CASE ((rowid / 12) % 4)
    WHEN 0 THEN '周四 20:00 开始发布观察，值守交接人是吴静，预计 22:00 前结束。'
    WHEN 1 THEN '客户把素材冻结时间提前到 16:00，回滚联系人仍为李欣。'
    WHEN 2 THEN '本次发布采用分批放量，第一轮观察 30 分钟后再决定是否继续。'
    WHEN 3 THEN '测试验收若晚于 18:30，发布会顺延到次日同一窗口。'
    ELSE '测试验收若晚于 18:30，发布会顺延到次日同一窗口。' END
  WHEN '泳镜保养说明' THEN CASE ((rowid / 12) % 4)
    WHEN 0 THEN '镜片用清水冲洗后自然晾干，不要用纸巾擦拭内侧防雾层。'
    WHEN 1 THEN '鼻桥有三档可调，首次下水前应在浅水区检查密封。'
    WHEN 2 THEN '泳镜盒底部有排水孔，收纳前需倒掉积水并保持通风。'
    WHEN 3 THEN '防雾层属于消耗部件，保养说明不承诺永久有效。'
    ELSE '防雾层属于消耗部件，保养说明不承诺永久有效。' END
  WHEN '社区体能活动通知' THEN CASE ((rowid / 12) % 4)
    WHEN 0 THEN '周末活动在社区篮球馆集合，现场分为拉伸和低强度循环两个区域。'
    WHEN 1 THEN '活动名额按签到顺序确认，主办方不提供代报名或代付款。'
    WHEN 2 THEN '本月体验课改到一楼多功能厅，鞋柜数量有限。'
    WHEN 3 THEN '志愿者会示范基础动作，参与者可随时退出并到休息区补水。'
    ELSE '志愿者会示范基础动作，参与者可随时退出并到休息区补水。' END
  WHEN '营后反馈问卷' THEN CASE ((rowid / 12) % 4)
    WHEN 0 THEN '问卷主要收集场地、节奏和换项体验，预计填写时间五分钟。'
    WHEN 1 THEN '反馈链接七天内有效，进阶课程选项可以跳过。'
    WHEN 2 THEN '主办方希望了解器材借用情况，不要求填写详细健康信息。'
    WHEN 3 THEN '若当天未完成全部环节，可在备注中写明主动退出的时间点。'
    ELSE '若当天未完成全部环节，可在备注中写明主动退出的时间点。' END
  WHEN '体验营集合说明' THEN CASE ((rowid / 12) % 4)
    WHEN 0 THEN '集合点改到体育公园东门，签到桌旁有蓝色指示牌。'
    WHEN 1 THEN '泳池更衣柜需要十元押金，离场时在前台退还。'
    WHEN 2 THEN '骑行环节不含车辆，头盔和租赁安排由参与者自行确认。'
    WHEN 3 THEN '现场先核对姓名再领号码布，迟到者从下一环节加入。'
    ELSE '现场先核对姓名再领号码布，迟到者从下一环节加入。' END
  WHEN '泳道临时调整' THEN CASE ((rowid / 12) % 4)
    WHEN 0 THEN '新手游道周六下午移到浅水区，18:00 后恢复原安排。'
    WHEN 1 THEN '第三泳道因设备检修暂停开放，前台会按到场顺序分流。'
    WHEN 2 THEN '周日晨间课程占用两条泳道，散客可使用靠窗一侧。'
    WHEN 3 THEN '水温维护完成前不开放深水区，最新状态以入口公告为准。'
    ELSE '水温维护完成前不开放深水区，最新状态以入口公告为准。' END
  WHEN '绿道路面维护' THEN CASE ((rowid / 12) % 4)
    WHEN 0 THEN '北段上午铺设防滑层，施工围挡内禁止通行。'
    WHEN 1 THEN '桥下两处积水点正在抽排，开放时间由现场人员确认。'
    WHEN 2 THEN '西入口照明检修，傍晚经过时需从南侧支路绕行。'
    WHEN 3 THEN '维护车会在 10:00 前离场，封闭标识撤除后才能进入。'
    ELSE '维护车会在 10:00 前离场，封闭标识撤除后才能进入。' END
  WHEN '基础装备发货提醒' THEN CASE ((rowid / 12) % 4)
    WHEN 0 THEN '订单分成两个包裹，手套先发，号码带预计晚一天出库。'
    WHEN 1 THEN '快递柜满柜时会转到小区服务点，取件码保持不变。'
    WHEN 2 THEN '包装内附尺码卡，未拆吊牌可按页面规则申请换货。'
    WHEN 3 THEN '物流单号已经生成，但承运商尚未完成首次揽收扫描。'
    ELSE '物流单号已经生成，但承运商尚未完成首次揽收扫描。' END
  WHEN '租车取消条款答复' THEN CASE ((rowid / 12) % 4)
    WHEN 0 THEN '用车前一天 18:00 前取消可退租金，押金原路返回。'
    WHEN 1 THEN '雨天停运由门店决定，已取车订单不适用未使用退款。'
    WHEN 2 THEN '头盔是单独租赁项目，需要在取车时核对尺码和数量。'
    WHEN 3 THEN '改期只能保留一次，新的时段仍以门店库存为准。'
    ELSE '改期只能保留一次，新的时段仍以门店库存为准。' END
  WHEN '升级课程推广' THEN CASE ((rowid / 12) % 4)
    WHEN 0 THEN '课程包含四次线下训练和一次录像分析，优惠价只保留到月底。'
    WHEN 1 THEN '销售邮件列出 1880 元套餐，报名和付款均由收件人自行决定。'
    WHEN 2 THEN '试听名额与正式课程分开，试听后不会自动生成付费订单。'
    WHEN 3 THEN '课程退费按已开课次数计算，详细条款在页面底部。'
    ELSE '课程退费按已开课次数计算，详细条款在页面底部。' END
  WHEN '雷雨安全提示' THEN CASE ((rowid / 12) % 4)
    WHEN 0 THEN '气象台预计午后有短时雷雨，听到雷声后场地会停止户外活动。'
    WHEN 1 THEN '绿道入口在闪电预警期间关闭，解除时间以现场广播为准。'
    WHEN 2 THEN '室内馆照常开放，但地库坡道可能积水，建议从东门进入。'
    WHEN 3 THEN '强对流期间不安排户外器材借用，已预约者可联系前台改期。'
    ELSE '强对流期间不安排户外器材借用，已预约者可联系前台改期。' END
  ELSE body_text END
WHERE subject IN ('家庭周末安排', '项目发布窗口', '泳镜保养说明', '社区体能活动通知', '营后反馈问卷', '体验营集合说明', '泳道临时调整', '绿道路面维护', '基础装备发货提醒', '租车取消条款答复', '升级课程推广', '雷雨安全提示');

-- 2026-08 third-pass clone repair: sender/thread context is part of a real
-- mailbox message and differentiates recurring notices without benchmark slots.
UPDATE messages
SET body_text = CASE (rowid % 7)
  WHEN 0 THEN body_text || char(10) || char(10) || '发件人：' || from_addr
  WHEN 1 THEN '来自 ' || from_addr || ' 的通知：' || body_text
  WHEN 2 THEN body_text || ' 如需补充，请回复 ' || from_addr || '。'
  WHEN 3 THEN '事项记录（' || from_addr || '）：' || body_text
  WHEN 4 THEN body_text || char(10) || '联系邮箱 ' || from_addr
  WHEN 5 THEN '由 ' || from_addr || ' 更新。' || body_text
  ELSE body_text || ' 原邮件联系人为 ' || from_addr || '。' END
WHERE subject IN ('家庭周末安排', '项目发布窗口', '泳镜保养说明', '社区体能活动通知', '营后反馈问卷', '体验营集合说明', '泳道临时调整', '绿道路面维护', '基础装备发货提醒', '租车取消条款答复', '升级课程推广', '雷雨安全提示');

DELETE FROM messages WHERE message_id IN ('msg_camp_brief_052', 'msg_upgrade_1880_052', 'msg_final_notice_052');
